//! `gen_legacy_gen_srs_dark_dex_keys` — **LEGACY / INSECURE** reproduction bin
//! for the pre-Hermez DarkDex W=128 keys and SDK proof/instances bundle.
//!
//! # ⚠  DO NOT USE FOR PRODUCTION  ⚠
//!
//! This bin exists **only** to reproduce the historical VK + proof/instances
//! files that were shipped into `tvm-sdk/tvm_vm/halo2_test_data/` before the
//! Hermez-anchored path was introduced. Production tvm-sdk verification MUST
//! use artifacts generated by the sibling bin
//! [`gen_hermez_kzg_and_dark_dex_keys`], which is anchored in the community-
//! audited Perpetual Powers of Tau ceremony (Hermez K=20).
//!
//! ## Why this is insecure
//!
//! Keys emitted here are keyed to a KZG SRS produced by
//! `halo2_base::utils::fs::gen_srs(K)`. That helper generates the trusted-setup
//! trapdoor **inside this process from RNG**, then writes the SRS to disk. The
//! trapdoor is not deleted — anyone with access to the machine / cache can
//! forge proofs against these keys. There is no ceremony, no audit, no
//! multi-party contribution: it is toxic waste kept in a folder.
//!
//! The Hermez path (see the sibling bin) replaces this trust root with a
//! byte-anchored SHA-256 of the Hermez K=20 raw SRS
//! (`80394564e2598883dbb5d7d61630287f34e29cdd806d7ef74f68acc6bffeb608`) and is
//! the only variant that should ever be embedded in tvm-sdk in production.
//!
//! ## Why keep this bin
//!
//! Backward compatibility. Older tvm-sdk unit tests still reference the
//! `dark_dex_w128_L{n}_(proof|instances).bin` blobs generated the old way.
//! Until every consumer of those blobs migrates to the Hermez-derived ones, we
//! keep this bin around so the exact old bytes can be regenerated on demand.
//! Once the migration completes this file should be deleted outright.
//!
//! ## Provenance
//!
//! Content lifted verbatim from the (now-removed) unit test
//! `dex_halo2_circuit::dark_dex_circuit_new::tests_with_synthetic_data::test_export_tvm_sdk_data_w128`.
//! Only glue was added: the same CWD-independence + fail-fast preflight the
//! Hermez bin uses, and CLI args instead of `TVM_SDK_EXPORT_DIR`.
//!
//! ## Usage
//!
//! ```bash
//! # from anywhere — bin chdirs to CARGO_MANIFEST_DIR for the vouchers.txt read.
//! cargo run --release --bin gen_legacy_gen_srs_dark_dex_keys -- --out ./generated_legacy
//! ```
//!
//! Emits under `<out>/`:
//!   - `dark_dex_w128_vk.bin`                — legacy VK (RawBytesUnchecked)
//!   - `dark_dex_w128_L{0,1,2,11}_proof.bin` — legacy proofs (chain_len ∈ {0,1,2,MAX_CHAIN_LEN})
//!   - `dark_dex_w128_L{0,1,2,11}_instances.bin` — 5 × 32-byte LE Fr instances

use std::fs;
use std::path::{Path, PathBuf};
use std::time::Instant;

use clap::Parser;
use halo2_base::halo2_proofs::halo2curves::ff::PrimeField;
use halo2_base::halo2_proofs::plonk::{keygen_pk, keygen_vk};
use halo2_base::halo2_proofs::SerdeFormat;
use halo2_base::utils::fs::gen_srs;
use halo2_base::utils::testing::{check_proof_with_instances, gen_proof_with_instances};

use dex_halo2_circuit::keygen::{W128Fixture, K};
use gosh_dense_balanced_tree::MAX_CHAIN_LEN;

/// RNG seed for the synthesized two-level tree. Matches the value the deleted
/// `test_export_tvm_sdk_data_w128` used, so the emitted bytes are bit-identical
/// to the historical shipped blobs.
const TWO_LEVEL_TREE_SEED: u64 = 99;

/// Chain lengths whose (proof, instances) pairs get emitted. Same enumeration
/// as the Hermez bin, so the file lists in both output directories align 1:1.
const SDK_TEST_CHAIN_LENS: [usize; 4] = [0, 1, 2, MAX_CHAIN_LEN];

const DARK_DEX_VK_BIN_FILENAME: &str = "dark_dex_w128_vk.bin";

fn sdk_proof_filename(chain_len: usize) -> String {
    format!("dark_dex_w128_L{}_proof.bin", chain_len)
}

fn sdk_instances_filename(chain_len: usize) -> String {
    format!("dark_dex_w128_L{}_instances.bin", chain_len)
}

#[derive(Parser, Debug)]
#[command(
    author,
    version,
    about = "LEGACY / INSECURE reproduction of pre-Hermez DarkDex W=128 keys and SDK proof/instances bundle"
)]
struct Args {
    /// Output directory for the legacy VK + (proof, instances) pairs.
    #[arg(long, default_value = "./generated_legacy")]
    out: PathBuf,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = Args::parse();

    // Same CWD-independence + fail-fast preflight as the Hermez bin — snapshot
    // user-supplied paths against the *initial* CWD, then chdir to
    // CARGO_MANIFEST_DIR so `load_first_voucher()`'s hardcoded "vouchers.txt"
    // read succeeds regardless of launch dir. Preflight-check that the file
    // exists so keygen doesn't burn time before hitting a trivial IO error.
    let initial_cwd = std::env::current_dir()?;
    args.out = absolutize(&initial_cwd, &args.out);
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let vouchers_path = manifest_dir.join("vouchers.txt");
    assert!(
        vouchers_path.is_file(),
        "vouchers.txt not found at {} — cannot synthesize W=128 fixture",
        vouchers_path.display(),
    );
    std::env::set_current_dir(&manifest_dir)?;

    fs::create_dir_all(&args.out)?;

    eprintln!("╔══════════════════════════════════════════════════════════════════╗");
    eprintln!("║  LEGACY / INSECURE gen_srs path — do NOT ship to production.     ║");
    eprintln!("║  Use gen_hermez_kzg_and_dark_dex_keys for real deployments.      ║");
    eprintln!("╚══════════════════════════════════════════════════════════════════╝");

    // --- 1. SRS (INSECURE — trapdoor generated in-process from RNG) --------
    eprintln!("PARAMS_DIR = {:?}", std::env::var("PARAMS_DIR"));
    eprintln!("[1/3] gen_srs(K={}) — self-generating trusted setup (INSECURE)...", K);
    let t = Instant::now();
    let srs = gen_srs(K);
    eprintln!("      done in {:?}", t.elapsed());

    // --- 2. Fixture + keygen ------------------------------------------------
    eprintln!("[2/3] Synthesizing W=128 fixture and running keygen (chain_len=1)...");
    let fixture = W128Fixture::synth(TWO_LEVEL_TREE_SEED);
    let keygen_circuit = fixture.build_keygen_circuit();

    let t = Instant::now();
    let vk = keygen_vk(&srs, &keygen_circuit)?;
    eprintln!("      keygen_vk: {:?}", t.elapsed());

    // Serialize VK — same format tvm-sdk's `read_vk` uses.
    let mut vk_bytes: Vec<u8> = Vec::new();
    vk.write(&mut vk_bytes, SerdeFormat::RawBytesUnchecked)?;
    let vk_path = args.out.join(DARK_DEX_VK_BIN_FILENAME);
    fs::write(&vk_path, &vk_bytes)?;
    eprintln!("      Wrote {} ({} B)", vk_path.display(), vk_bytes.len());

    let t = Instant::now();
    let pk = keygen_pk(&srs, vk, &keygen_circuit)?;
    eprintln!("      keygen_pk: {:?}", t.elapsed());
    let break_points = keygen_circuit.base_circuit_builder.borrow().break_points();

    // --- 3. Emit one (proof, instances) pair per chain_len -----------------
    eprintln!(
        "[3/3] Emitting proof/instances pairs for chain_len ∈ {:?}...",
        SDK_TEST_CHAIN_LENS
    );
    for &chain_len in &SDK_TEST_CHAIN_LENS {
        let (prover_circuit, instances, _final_root) =
            fixture.build_prover_circuit(chain_len, break_points.clone());
        assert_eq!(instances.len(), 5, "SDK instance layout is 5 Fr");

        eprintln!("      [L{}] proving...", chain_len);
        let t = Instant::now();
        let proof_bytes = gen_proof_with_instances(&srs, &pk, prover_circuit, &[&instances]);
        eprintln!(
            "      [L{}] proof = {} B in {:?}; sanity-verifying...",
            chain_len,
            proof_bytes.len(),
            t.elapsed()
        );
        check_proof_with_instances(&srs, pk.get_vk(), &proof_bytes, &[&instances], true);

        // 5 × 32-byte LE Fr = 160 B; tvm-sdk decodes via `Fr::from_bytes_le` / `Fr::from_repr`.
        let mut instances_bytes: Vec<u8> = Vec::with_capacity(5 * 32);
        for fr in &instances {
            instances_bytes.extend_from_slice(fr.to_repr().as_ref());
        }
        debug_assert_eq!(instances_bytes.len(), 160);

        let proof_path = args.out.join(sdk_proof_filename(chain_len));
        let instances_path = args.out.join(sdk_instances_filename(chain_len));
        fs::write(&proof_path, &proof_bytes)?;
        fs::write(&instances_path, &instances_bytes)?;
        eprintln!(
            "      [L{}] wrote {} ({} B) and {} ({} B)",
            chain_len,
            proof_path.display(),
            proof_bytes.len(),
            instances_path.display(),
            instances_bytes.len()
        );
    }

    eprintln!();
    eprintln!(
        "Done — wrote legacy VK + {} (proof, instances) pairs to {}",
        SDK_TEST_CHAIN_LENS.len(),
        args.out.display()
    );
    eprintln!("REMINDER: these bytes come from self-generated toxic-waste keys —");
    eprintln!("they are for historical / test reproduction only, NEVER production.");
    Ok(())
}

/// Resolve `p` against `base` if relative; return unchanged if already absolute.
/// Snapshot user-supplied paths against the *initial* CWD before we chdir to
/// `CARGO_MANIFEST_DIR` for the vouchers.txt read.
fn absolutize(base: &Path, p: &Path) -> PathBuf {
    if p.is_absolute() {
        p.to_path_buf()
    } else {
        base.join(p)
    }
}
